package com.driveflow.servlet;
import com.driveflow.model.Customer; import com.driveflow.store.DataStore; import com.driveflow.util.Flash; import javax.servlet.*; import javax.servlet.http.*; import java.io.IOException;
public class CustomerServlet extends HttpServlet {
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if("edit".equals(req.getParameter("action"))){req.setAttribute("editCustomer",DataStore.customer(Integer.parseInt(req.getParameter("id"))));req.setAttribute("customers",DataStore.customers);req.getRequestDispatcher("/views/customers.jsp").forward(req,resp);return;}if("delete".equals(req.getParameter("action"))){int id=Integer.parseInt(req.getParameter("id"));boolean used=false;for(com.driveflow.model.Rental r:DataStore.rentals)if(r.getCustomerId()==id)used=true;if(!used){Customer c=DataStore.customer(id);if(c!=null)DataStore.customers.remove(c);Flash.set(req.getSession(),"success","Customer removed successfully.");}else Flash.set(req.getSession(),"error","Customer cannot be deleted because rental history exists.");resp.sendRedirect(req.getContextPath()+"/customers");return;}req.setAttribute("customers",DataStore.customers);req.getRequestDispatcher("/views/customers.jsp").forward(req,resp);}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{try{String action=req.getParameter("action");String name=req.getParameter("name").trim(),email=req.getParameter("email").trim(),phone=req.getParameter("phone").trim(),license=req.getParameter("licenseNo").trim(),address=req.getParameter("address").trim();if("edit".equals(action)){Customer c=DataStore.customer(Integer.parseInt(req.getParameter("id")));c.setName(name);c.setEmail(email);c.setPhone(phone);c.setLicenseNo(license);c.setAddress(address);Flash.set(req.getSession(),"success","Customer updated successfully.");}else{DataStore.customers.add(new Customer(DataStore.nextCustomerId(),name,email,phone,license,address));Flash.set(req.getSession(),"success","Customer added successfully.");}}catch(Exception e){Flash.set(req.getSession(),"error","Could not save customer: "+e.getMessage());}resp.sendRedirect(req.getContextPath()+"/customers");}
}
